conditions.value_template:
{% set b_groups = ['sensor.mean_moisture_b1', 'sensor.mean_moisture_b2', 'sensor.mean_moisture_b3', 'sensor.mean_moisture_b4'] %}
{% set b_sensors = expand(b_groups) | map(attribute='attributes.entity_id') | sum(start=[]) | unique | list %}
{% set ns = namespace(latest=0) %}
{% for s in expand(b_sensors) %}
  {% if s.state not in ['unknown', 'unavailable'] %}
    {% set ts = as_timestamp(s.last_updated, 0) %}
    {% if ts > ns.latest %}
      {% set ns.latest = ts %}
    {% endif %}
  {% endif %}
{% endfor %}
{{ (as_timestamp(now()) - ns.latest) >= 86400 }}
